package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.Dataset;
import org.eclipse.rdf4j.query.algebra.Projection;
import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.ArrayBindingSet;
import org.eclipse.rdf4j.query.algebra.evaluation.BindingSetOrigin;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.GraphFrameBindings;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.QueryEvaluationContext;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.evaluationsteps.ProjectionQueryEvaluationStep;
import org.eclipse.rdf4j.query.impl.MapBindingSet;
import org.junit.jupiter.api.Test;

class NativeBindingDomainArrayAddAllTest {
	private static final Value OLD = SimpleValueFactory.getInstance().createIRI("urn:array-addall:old");
	private static final Value NEW = SimpleValueFactory.getInstance().createIRI("urn:array-addall:new");
	private static final Value PAYLOAD = SimpleValueFactory.getInstance().createIRI("urn:array-addall:payload");

	@Test
	void sameSchemaUnwrittenGraphMetadataCannotSupplyAnEqualTargetValue() {
		String[] names = { "privateGraph" };
		ArrayBindingSet target = new ArrayBindingSet(names);
		target.setBinding("privateGraph", OLD);
		ArrayBindingSet source = new ArrayBindingSet(names);
		GraphFrameBindings.preserve(suppliedGraph(OLD), source);
		assertFalse(source.hasBinding("privateGraph"));
		assertFalse(GraphFrameBindings.isSupplied(target, "privateGraph"));

		target.addAll(source);

		assertSame(OLD, target.getValue("privateGraph"));
		assertFalse(GraphFrameBindings.isSupplied(target, "privateGraph"),
				"matching schema and metadata do not make an unwritten slot a graph input");
	}

	@Test
	void differentSchemaUnacceptedGraphMetadataCannotReplaceTargetAuthority() {
		ArrayBindingSet target = new ArrayBindingSet("privateGraph");
		target.setBinding("privateGraph", OLD);
		GraphFrameBindings.supply(target, "privateGraph", OLD);
		ArrayBindingSet source = new ArrayBindingSet("unaccepted");
		source.setBinding("unaccepted", PAYLOAD);
		GraphFrameBindings.preserve(suppliedGraph(NEW), source);
		assertTrue(GraphFrameBindings.isSupplied(target, "privateGraph"));
		assertFalse(source.hasBinding("privateGraph"));

		target.addAll(source);

		assertSame(OLD, target.getValue("privateGraph"));
		assertTrue(GraphFrameBindings.isSupplied(target, "privateGraph"),
				"an unrelated field outside the target schema cannot replace its graph authority");
	}

	@Test
	void acceptedBoundGraphSourceStillTransfersItsAuthority() {
		String[] names = { "privateGraph" };
		ArrayBindingSet target = new ArrayBindingSet(names);
		target.setBinding("privateGraph", OLD);
		ArrayBindingSet source = new ArrayBindingSet(names);
		source.setBinding("privateGraph", OLD);
		GraphFrameBindings.supply(source, "privateGraph", OLD);
		assertFalse(GraphFrameBindings.isSupplied(target, "privateGraph"));

		target.addAll(source);

		assertSame(OLD, target.getValue("privateGraph"));
		assertTrue(GraphFrameBindings.isSupplied(target, "privateGraph"));
	}

	@Test
	void sameSchemaUnwrittenRequestParameterCannotReplaceTargetParameter() {
		String[] names = { "parameter", "payload" };
		ArrayBindingSet target = new ArrayBindingSet(names);
		BindingSetOrigin.set(target, requestOrigin(OLD));
		target.setBinding("payload", PAYLOAD);
		ArrayBindingSet source = new ArrayBindingSet(names);
		BindingSetOrigin.set(source, requestOrigin(NEW));
		source.setBinding("payload", NEW);
		assertFalse(source.hasBinding("parameter"));
		assertSame(OLD, BindingSetOrigin.of(target).parameterValue("parameter"));

		target.addAll(source);

		assertSame(OLD, BindingSetOrigin.of(target).parameterValue("parameter"),
				"same-schema addAll writes payload only; its hidden request parameter must not replace target state");
		assertFalse(target.hasBinding("parameter"));
		assertSame(NEW, target.getValue("payload"));
	}

	@Test
	void sourceRequestNameOutsideTargetSchemaCannotReplaceItsParameter() {
		ArrayBindingSet target = new ArrayBindingSet("payload");
		BindingSetOrigin.set(target, requestOrigin(OLD));
		target.setBinding("payload", PAYLOAD);
		ArrayBindingSet source = new ArrayBindingSet("parameter", "payload");
		BindingSetOrigin.set(source, requestOrigin(NEW));
		source.setBinding("parameter", NEW);
		source.setBinding("payload", NEW);
		assertSame(OLD, BindingSetOrigin.of(target).parameterValue("parameter"));

		target.addAll(source);

		assertSame(OLD, BindingSetOrigin.of(target).parameterValue("parameter"),
				"source metadata cannot describe a mapping that the fixed target schema did not accept");
		assertFalse(target.hasBinding("parameter"));
		assertSame(NEW, target.getValue("payload"));
	}

	private static BindingSetOrigin requestOrigin(Value parameter) {
		MapBindingSet input = new MapBindingSet();
		input.addBinding("parameter", parameter);
		return BindingSetOrigin.of(BindingSetOrigin.optimizationInput(input));
	}

	private static BindingSet suppliedGraph(Value graph) {
		Projection lowering = new Projection(new SingletonSet());
		lowering.setProjectionContext(Var.of("callerGraph"));
		lowering.setInheritedGraphParameter("privateGraph");
		MapBindingSet caller = new MapBindingSet();
		caller.addBinding("callerGraph", graph);
		return ProjectionQueryEvaluationStep.withInheritedGraphInput(lowering, caller,
				new QueryEvaluationContext.Minimal((Dataset) null));
	}
}
